#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long h;
    int idx;
} Item;

int cmp(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->h > y->h) return -1;
    if (x->h < y->h) return 1;
    return x->idx - y->idx;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Item *items = (Item *)malloc((size_t)N * sizeof(Item));
    for (int i = 0; i < N; ++i) {
        scanf("%lld", &items[i].h);
        items[i].idx = i;
    }

    qsort(items, (size_t)N, sizeof(Item), cmp);

    char *active = (char *)calloc((size_t)N, sizeof(char));
    int runs = 0, maxRuns = 0;

    int i = 0;
    while (i < N) {
        long long h = items[i].h;
        int j = i;

        while (j < N && items[j].h == h) {
            int idx = items[j].idx;
            active[idx] = 1;

            int cnt = 0;
            if (idx > 0 && active[idx - 1]) ++cnt;
            if (idx + 1 < N && active[idx + 1]) ++cnt;

            if (cnt == 0) {
                ++runs;
            } else if (cnt == 2) {
                --runs;
            }

            ++j;
        }

        if (runs > maxRuns) maxRuns = runs;
        i = j;
    }

    printf("%d\n", maxRuns + 1);

    free(items);
    free(active);
    return 0;
}
